"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[85824],{41752:e=>{e.exports=JSON.parse('{"functions":[{"name":"GetStatus","desc":"The player\'s `ReviveRules.Status`.","params":[{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":393,"path":"src/ServerStorage/SharedModules/ReviveService.luau"}},{"name":"Initialize","desc":"Turn off auto respawn and wire death, purchase, ad and receipts. Call once,\\nafter `ReviveCredits.Initialize` and before `ReceiptRouter.Start`.","params":[],"returns":[],"function_type":"static","source":{"line":402,"path":"src/ServerStorage/SharedModules/ReviveService.luau"}}],"properties":[],"types":[],"name":"ReviveService","desc":"Life and death in the Game Instance. Characters no longer respawn by\\nthemselves (`CharacterAutoLoads = false`): a death is final until the player\\nrevives with 99 R$ (no cap) or with the run\'s one rewarded ad.\\n\\nEvery \\"Revive\\" receipt first becomes a saved credit (ReviveCredits); a down\\nplayer then spends it at once, so a paid revive is never lost. Revive =\\n`LoadCharacter` at the normal spawn, full health, with the Tools held at death.\\n\\nState is keyed by UserId, so a down player who disconnects and rejoins comes\\nback down, with the same \\"ad used\\" flag and Tools.\\n\\nWhen every player is down (a disconnected player in rejoin grace who was\\nalive counts as alive) a shared `ALL_DOWN_SECONDS` countdown starts. A\\npurchase prompt, ad or revive in flight at 0 holds the end up to\\n`HOLD_MAX_SECONDS`. At the end the run is over: game over `ALL_DOWN`, then\\neveryone goes to the lobby.\\n\\nSee docs/systems/revive.md.","realm":["Server"],"source":{"line":25,"path":"src/ServerStorage/SharedModules/ReviveService.luau"}}')}}]);